      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 60 * 60,
      path: '/',
    });

    // 使用済みのワンタイムトークンを削除
    cookieStore.delete('oauth_state');
    cookieStore.delete('oauth_code_verifier');

    // ダッシュボードにリダイレクト
    return redirect('/');

  } catch (error) {
    console.error('OAuth callback error:', error);
    return redirect('/login?error=callback_failed');
  }
}

